package com.ecommerce.cart; import com.ecommerce.user.User; import jakarta.persistence.*; import java.time.Instant; import java.util.*;
@Entity @Table(name="carts") public class Cart { @Id @GeneratedValue(strategy=GenerationType.UUID) UUID id; @OneToOne(fetch=FetchType.LAZY) @JoinColumn(name="user_id",unique=true,nullable=false) User user; @OneToMany(mappedBy="cart",cascade=CascadeType.ALL,orphanRemoval=true,fetch=FetchType.EAGER) List<CartItem> items=new ArrayList<>(); @Column(name="created_at",nullable=false,updatable=false) Instant createdAt; @Column(name="updated_at",nullable=false) Instant updatedAt; @PrePersist void c(){createdAt=Instant.now();updatedAt=createdAt;} @PreUpdate void u(){updatedAt=Instant.now();} public UUID getId(){return id;} public User getUser(){return user;} public List<CartItem> getItems(){return items;} public void setUser(User v){user=v;} }
